namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    public static int DiscountCentsFor(int subtotalCents, LoyaltyTier loyaltyTier) =>
        subtotalCents * RatePercentOf(loyaltyTier) / 100;

    private static int RatePercentOf(LoyaltyTier loyaltyTier) => loyaltyTier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        _ => throw new ArgumentOutOfRangeException(nameof(loyaltyTier))
    };
}

