namespace CheckoutPricing.Domain;

public static class ShippingFeePolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromPayableCents = 5_000;

    public static int FeeCentsFor(int payableTotalCents, LoyaltyTier loyaltyTier, bool express) =>
        express ? ExpressFeeFor(loyaltyTier) : StandardFeeFor(payableTotalCents, loyaltyTier);

    private static int ExpressFeeFor(LoyaltyTier loyaltyTier) =>
        loyaltyTier == LoyaltyTier.Platinum ? 0 : ExpressFeeCents;

    private static int StandardFeeFor(int payableTotalCents, LoyaltyTier loyaltyTier) =>
        loyaltyTier is LoyaltyTier.Gold or LoyaltyTier.Platinum || payableTotalCents >= FreeStandardFromPayableCents
            ? 0
            : StandardFeeCents;
}

